def Composition(text, k):
    res = []
    for i in range(len(text) - k + 1):
        res.append(text[i:i+k])
    return res

Text = ''
k = 100
res = Composition(Text, k)
#We need to use below code to ensure that every kmer generated is separated by a single space, just copy it from the file generated
file = open('C:/Users/Matthew/Downloads/solution.txt', 'w')#Change it with your desired location
j = 0
while j < len(res):
  file.write(res[j] + ' ')
  j += 1

file.close()